On recode les mesures puis on les compare à R/inegalites.R (testé : invariance d’échelle, principe des transferts, identités de décomposition).
rng = {
  // Générateur pseudo-aléatoire reproductible : graine = jour + id d'exercice + salt.
  // (Source unique : scripts/test_exercices.R évalue cette même cellule avec Node.)
  const today = new Date().toISOString().slice(0, 10);
  const hash = (s) =&gt; {
    let h = 1779033703 ^ s.length;
    for (let i = 0; i &lt; s.length; i++) { h = Math.imul(h ^ s.charCodeAt(i), 3432918353); h = (h &lt;&lt; 13) | (h &gt;&gt;&gt; 19); }
    return h &gt;&gt;&gt; 0;
  };
  const mulberry32 = (a) =&gt; () =&gt; {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a &gt;&gt;&gt; 15), 1 | a);
    t = (t + Math.imul(t ^ (t &gt;&gt;&gt; 7), 61 | t)) ^ t;
    return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296;
  };
  return (id, salt = 0, day = today) =&gt; {
    const u = mulberry32(hash(`${day}|${id}|${salt}`));
    const int = (a, b) =&gt; a + Math.floor(u() * (b - a + 1));
    const pick = (arr) =&gt; arr[Math.floor(u() * arr.length)];
    const normal = () =&gt; Math.sqrt(-2 * Math.log(1 - u())) * Math.cos(2 * Math.PI * u());
    return { u, int, pick, normal };
  };
}

